const input = $json || {};
const categories = input.config?.categories?.allowed || [
  'developpement',
  'nutrition',
  'sante',
  'culture',
  'musique',
  'sciences',
  'loisirs',
  'parentalite',
  'nature',
  'lecture',
  'autre'
];

return [{
  json: {
    mode: input.mode || 'proposal',
    selectedCategory: input.selectedCategory || null,
    selectedTopic: input.selectedTopic || null,
    categories,
    config: input.config || {},
    familyContext: input.familyContext || null
  }
}];

const context = $json.child ? $json : ($json.familyContext || {});
const categories = $('Load Planner Input').first().json.categories;
const recent = context.recentCategories || [];
const recentSet = new Set(recent.slice(0, 3));
const allowed = categories.filter(category => !recentSet.has(category));
const candidateCategories = allowed.length > 0 ? allowed : categories;

return [{
  json: {
    familyContext: context,
    categories,
    candidateCategories,
    selectedCategory: $('Load Planner Input').first().json.selectedCategory,
    selectedTopic: $('Load Planner Input').first().json.selectedTopic,
    mode: $('Load Planner Input').first().json.mode,
    proposal: {
      text: 'Préparons le prochain meeting familial.',
      choices: [
        { id: 'auto', label: 'Laisse FamilyOS choisir' },
        { id: 'category', label: 'Choisir une catégorie' },
        { id: 'topic', label: 'Choisir directement un sujet' },
        { id: 'backlog', label: 'Voir les idées en attente' }
      ],
      categories: candidateCategories
    }
  }
}];
